(function(){
  'use strict';
  const MASTER='8283ab91b10f89ac758d09ecf5fb4d6343536600a06dd468b1cc1ecf4ec747c4';
  const doc=window.ATLAS_CLARUS_DATA||{};
  const colors=doc.colors||[];
  const libraryViews=doc.views||{};
  let selected=colors.find(c=>c.id===4665)||colors[0]; let arbeReference=null; let palette=[];
  let filtered=colors.slice(); let page=0; let activeView='core'; const perPage=96;
  const $=s=>document.querySelector(s);
  const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const views=[...document.querySelectorAll('.view')];
  function route(){const id=(location.hash||'#home').slice(1);views.forEach(v=>v.classList.toggle('active',v.id===id));if(id==='wheel')drawWheel();if(id==='appearance')drawSimulation();scrollTo(0,0)}
  addEventListener('hashchange',route);
  function luminance(rgb){return .2126*rgb[0]+.7152*rgb[1]+.0722*rgb[2]}
  function selectedHtml(c){return `<div class="selected-swatch" style="background:${esc(c.hex)}"></div><p class="eyebrow">FROZEN REFERENCE IDENTITY</p><h2>${esc(c.ref)}</h2><dl><dt>atlas_row_id</dt><dd>${c.id}</dd><dt>Human row</dt><dd>${c.id+1}</dd><dt>RGB</dt><dd>${c.rgb.join(' / ')}</dd><dt>HEX</dt><dd>${esc(c.hex)}</dd><dt>CIELAB</dt><dd>${c.lab.map(n=>Number(n).toFixed(2)).join(' / ')}</dd><dt>Master</dt><dd>verified metadata</dd></dl><div class="selection-actions"><button data-add-palette>Add to palette</button><button data-open-wheel>Open in Wheel</button><button data-copy>Copy identity</button></div>`}
  function select(c){selected=c;$('#selection').innerHTML=selectedHtml(c);$('#wheel-selection').innerHTML=selectedHtml(c);document.querySelectorAll('[data-add-palette]').forEach(b=>b.onclick=()=>addPalette(c));document.querySelectorAll('[data-open-wheel]').forEach(b=>b.onclick=()=>{location.hash='wheel'});document.querySelectorAll('[data-copy]').forEach(b=>b.onclick=()=>copy(`${c.ref} | ${c.hex} | atlas_row_id ${c.id} | master_sha256 ${MASTER}`));drawSimulation();renderWheelCards()}
  async function copy(s){try{await navigator.clipboard.writeText(s)}catch(_){const t=document.createElement('textarea');t.value=s;document.body.append(t);t.select();document.execCommand('copy');t.remove()}}
  function render(){const start=page*perPage;const rows=filtered.slice(start,start+perPage);$('#colour-grid').innerHTML='';rows.forEach(c=>{const b=document.createElement('button');b.className='colour-card'+(luminance(c.rgb)>165?' dark-text':'');b.style.setProperty('--swatch',c.hex);b.innerHTML=`<b>${esc(c.ref)}</b><small>${esc(c.hex)} · ID ${c.id}</small>`;b.onclick=()=>select(c);$('#colour-grid').append(b)});const pages=Math.max(1,Math.ceil(filtered.length/perPage)),view=libraryViews[activeView];$('#library-status').innerHTML=`<b>${esc(view?.name||'HLC Core Reference')}</b> · ${esc(view?.status||'EXACT_ATLAS')} · ${filtered.length.toLocaleString('en')} shown · source observations ${(view?.ids?.length||colors.length).toLocaleString('en')} · master ${MASTER.slice(0,12)}…`;$('#page-info').textContent=`Page ${page+1} / ${pages}`;$('#prev-page').disabled=page===0;$('#next-page').disabled=page>=pages-1}
  function filter(){const q=$('#search').value.trim().toUpperCase(),l=$('#lightness').value,view=libraryViews[activeView],allowed=new Set((view?.ids||colors.map(c=>c.id)).map(Number));filtered=colors.filter(c=>allowed.has(c.id)&&(l==='all'||Math.round(c.lab[0])===Number(l))&&(!q||c.ref.includes(q)||c.hex.toUpperCase().includes(q)||String(c.id)===q));page=0;render()}
  for(let l=5;l<=95;l+=5){const o=document.createElement('option');o.value=l;o.textContent=`L* ${String(l).padStart(3,'0')}`;$('#lightness').append(o)}
  Object.entries(libraryViews).forEach(([key,v])=>{const o=document.createElement('option');o.value=key;o.textContent=v.name;$('#library-view').append(o)});$('#library-view').onchange=()=>{activeView=$('#library-view').value;filter()};$('#search').oninput=filter;$('#lightness').onchange=filter;$('#clear-search').onclick=()=>{$('#search').value='';$('#lightness').value='all';filter()};$('#prev-page').onclick=()=>{page--;render()};$('#next-page').onclick=()=>{page++;render()};
  function hcl(c){const m=c.ref.match(/H(\d+)_L(\d+)_C(\d+)/);return m?m.slice(1).map(Number):[0,c.lab[0],0]}
  function hueDistance(a,b){const d=Math.abs(a-b)%360;return Math.min(d,360-d)}
  function nearestHlc(H,L,C,exclude=-1){return colors.reduce((best,c)=>{if(c.id===exclude)return best;const q=hcl(c),d=hueDistance(q[0],H)**2+(q[1]-L)**2*5+(q[2]-C)**2*.8;return !best||d<best.d?{c,d}:best},null).c}
  function renderWheelCards(){if(!selected||!$('#harmony-cards'))return;const [H,L,C]=hcl(selected);$('#contrast-preview').style.background=selected.hex;$('#illumination-card').innerHTML=`<dt>Reference</dt><dd>${selected.ref}</dd><dt>Master Lab</dt><dd>${selected.lab.map(n=>Number(n).toFixed(2)).join(' / ')}</dd><dt>Recorded status</dt><dd>Identity evidence</dd>`;$('#arbe-card').innerHTML=arbeReference?`<p><b>${arbeReference.ref}</b> → <b>${selected.ref}</b></p><dl><dt>ΔH address</dt><dd>${hueDistance(hcl(arbeReference)[0],H).toFixed(0)}°</dd><dt>Identity mutation</dt><dd>NONE</dd></dl>`:'<p>No comparison reference locked.</p>';const rule=$('#harmony-rule').value;const offsets=rule==='analogous'?[-30,30]:rule==='triadic'?[120,240]:[180];const hs=[selected,...offsets.map(o=>nearestHlc((H+o+360)%360,L,C,selected.id))];$('#harmony-cards').innerHTML='';hs.forEach((c,i)=>{const b=document.createElement('button');b.className='mini-card';b.innerHTML=`<i style="background:${c.hex}"></i><b>${i?'Related':'Base'}</b><small>${c.ref}</small>`;b.onclick=()=>select(c);$('#harmony-cards').append(b)});$('#tone-ramp').innerHTML='';for(let l=5;l<=95;l+=10){const c=nearestHlc(H,l,C);const b=document.createElement('button');b.className='tone-button';b.style.background=c.hex;b.innerHTML=`<small>${l}</small>`;b.title=c.ref;b.onclick=()=>select(c);$('#tone-ramp').append(b)}$('#measurement-target').innerHTML=`<span class="eyebrow">ORIGINAL ATLAS IDENTITY</span><h3>${selected.ref}</h3><p>Row ${selected.id} · Master Lab ${selected.lab.map(n=>Number(n).toFixed(2)).join(' / ')}</p><p>Frozen identity remains unchanged.</p>`;renderProfiles();renderPalette()}
  $('#harmony-rule').onchange=renderWheelCards;$('#lock-reference').onclick=()=>{arbeReference=selected;renderWheelCards()};
  try{palette=JSON.parse(localStorage.getItem('atlasClarusSharedPaletteV1')||'[]').map(id=>colors.find(c=>c.id===Number(id))).filter(Boolean).slice(0,64)}catch(_){palette=[]}
  function savePalette(){try{localStorage.setItem('atlasClarusSharedPaletteV1',JSON.stringify(palette.map(c=>c.id)))}catch(_){}renderPalette()}
  function addPalette(c){if(!palette.some(x=>x.id===c.id))palette.push(c);savePalette();$('#palette-drawer').classList.add('open')}
  function renderPalette(){const box=$('#palette-list'),drawer=$('#drawer-palette-list');if(box){box.innerHTML=palette.length?'':'<p class="boundary">No identities added yet.</p>';palette.forEach(c=>{const b=document.createElement('button');b.className='palette-chip';b.innerHTML=`<i style="background:${c.hex}"></i><b>${c.ref}</b>`;b.onclick=()=>select(c);box.append(b)})}$('#palette-count').textContent=palette.length;drawer.innerHTML=palette.length?'':'<p class="boundary">Select a colour in the Hover Library and choose “Add to palette”.</p>';palette.forEach(c=>{const row=document.createElement('div');row.className='drawer-item';row.innerHTML=`<i style="background:${c.hex}"></i><span><b>${c.ref}</b><small>${c.hex} · row ${c.id}</small></span><button aria-label="Remove ${c.ref}">×</button>`;row.querySelector('span').onclick=()=>{select(c);location.hash='wheel'};row.querySelector('button').onclick=()=>{palette=palette.filter(x=>x.id!==c.id);savePalette()};drawer.append(row)})}
  $('#add-palette').onclick=()=>addPalette(selected);$('#clear-palette').onclick=$('#drawer-clear').onclick=()=>{palette=[];savePalette()};$('#export-palette').onclick=()=>exportPalette('clarus');$('#palette-toggle').onclick=()=>$('#palette-drawer').classList.add('open');$('#palette-close').onclick=()=>$('#palette-drawer').classList.remove('open');
  function download(name,data,type){const a=document.createElement('a'),blob=data instanceof Uint8Array?new Blob([data],{type}):new Blob([data],{type});a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1200)}
  function exportPalette(kind){const E=window.ATLAS_CLARUS_EXPORTS,status=$('#export-status');if(!palette.length){status.textContent='Add at least one colour before exporting.';return}if(kind==='ase'){const bytes=E.ase(palette),back=E.readAse(bytes),ok=back.length===palette.length&&back.every((x,i)=>x.ref===palette[i].ref&&x.rgb.every((v,j)=>v===palette[i].rgb[j]));if(!ok){status.textContent='ASE readback failed. Export blocked.';return}download('ATLAS_Clarus_Palette.ase',bytes,'application/octet-stream');status.textContent=`ASE exported and read back: ${palette.length} exact RGB swatches.`}else if(kind==='tokens'){download('ATLAS_Clarus_Palette.tokens.json',JSON.stringify(E.tokens(palette,MASTER),null,2),'application/json');status.textContent='Figma-compatible Design Tokens exported.'}else if(kind==='css'){download('ATLAS_Clarus_Palette.css',E.css(palette,MASTER),'text/css');status.textContent='CSS custom properties exported.'}else{download('ATLAS_Clarus_Palette.clarus.json',JSON.stringify(E.clarus(palette,MASTER),null,2),'application/json');status.textContent='Clarus identity and provenance JSON exported.'}}
  document.querySelectorAll('[data-palette-export]').forEach(b=>b.onclick=()=>exportPalette(b.dataset.paletteExport));
  function renderProfiles(){const specs=[['sRGB','ACTIVE OUTPUT',selected.hex],['Display P3','COMPARISON',`linear-gradient(135deg,${selected.hex},#111)`],['Adobe RGB','COMPARISON',`linear-gradient(135deg,#111,${selected.hex})`],['FOGRA55 CMYKOGV','FEASIBILITY ONLY','linear-gradient(135deg,#00a9ce,#ec008c 34%,#fff200 67%,#171717)']];$('#profile-cards').innerHTML=specs.map(x=>`<article class="profile-card"><i style="background:${x[2]}"></i><div><span>${x[1]}</span><h4>${x[0]}</h4><small>${x[0]==='sRGB'?'Bound screen representation':'Profile transform not bound in offline bundle'}</small></div></article>`).join('')}
  $('#bind-measurement').onclick=()=>{const v=['measured-l','measured-a','measured-b'].map(id=>Number($('#'+id).value)),inst=$('#instrument').value.trim();if(v.some(x=>!Number.isFinite(x))||!inst){$('#measurement-result').textContent='Enter all three Lab values and the measurement source.';return}const d=Math.sqrt(v.reduce((s,x,i)=>s+(x-selected.lab[i])**2,0));$('#measurement-result').innerHTML=`Entered result appended locally for review: <b>ΔE*ab ${d.toFixed(3)}</b> · source ${esc(inst)}. This is not ΔE00 and is not stored in the master.`};
  function drawWheel(){const cv=$('#wheel-canvas');if(!cv)return;const ctx=cv.getContext('2d');const w=cv.width,h=cv.height,cx=w/2,cy=h/2,R=w*.43;ctx.clearRect(0,0,w,h);const grad=ctx.createRadialGradient(cx,cy,25,cx,cy,R);grad.addColorStop(0,'#e8e5df');grad.addColorStop(.45,'#75777b');grad.addColorStop(1,'#171c23');ctx.fillStyle=grad;ctx.beginPath();ctx.arc(cx,cy,R,0,Math.PI*2);ctx.fill();const [sh,sl,sc]=hcl(selected);const layer=colors.filter(c=>Math.abs(hcl(c)[1]-sl)<2.6);layer.forEach(c=>{const [H,,C]=hcl(c);const a=(H-90)*Math.PI/180;const r=Math.min(R,C/105*R);ctx.fillStyle=c.hex;ctx.beginPath();ctx.arc(cx+Math.cos(a)*r,cy+Math.sin(a)*r,3.2,0,Math.PI*2);ctx.fill()});const a=(sh-90)*Math.PI/180,r=Math.min(R,sc/105*R);ctx.strokeStyle='#fff';ctx.lineWidth=4;ctx.beginPath();ctx.arc(cx+Math.cos(a)*r,cy+Math.sin(a)*r,10,0,Math.PI*2);ctx.stroke();ctx.fillStyle='#fff';ctx.font='18px system-ui';ctx.textAlign='center';ctx.fillText(`L* ${sl}`,cx,cy+6)}
  const mats={paper:[.98,.97,.94],polymer:[1.02,1.02,1.03],metal:[.78,.82,.86],textile:[.86,.84,.81],glass:[.8,.9,1],wood:[.92,.78,.62]};
  function drawSimulation(){const cv=$('#sim-canvas');if(!cv||!selected)return;const ctx=cv.getContext('2d'),w=cv.width,h=cv.height;const mat=$('#material').value,fin=$('#finish').value,ill=$('#illuminant').value,angle=Number($('#angle').value),depth=Number($('#depth').value)/100;$('#angle-output').value=angle+'°';const light=ill==='A'?[1.16,.88,.62]:ill==='D65'?[.93,.98,1.1]:[1.04,1,.92];const base=selected.rgb.map((v,i)=>v*mats[mat][i]*light[i]);const img=ctx.createImageData(w,h);for(let y=0;y<h;y++)for(let x=0;x<w;x++){const p=(y*w+x)*4,n=Math.sin(x*.14)+Math.cos(y*.17)+Math.sin((x+y)*.037),glint=Math.pow(Math.max(0,1-Math.abs(x/w-(.25+angle/160))),fin==='gloss'?18:fin==='metallic'?7:40)*(fin==='gloss'?90:fin==='metallic'?120:25);for(let i=0;i<3;i++)img.data[p+i]=Math.max(0,Math.min(255,base[i]*(1+n*depth*.075)+glint));img.data[p+3]=255}ctx.putImageData(img,0,0);ctx.fillStyle='#000b';ctx.fillRect(20,h-85,520,62);ctx.fillStyle='#fff';ctx.font='bold 22px system-ui';ctx.fillText(selected.ref,38,h-52);ctx.font='15px system-ui';ctx.fillStyle='#cbd5e1';ctx.fillText(`${mat} · ${fin} · ${ill} · ${angle}° · simulated screen appearance`,38,h-28);$('#sim-caption').textContent=`Frozen source: ${selected.ref} · ${selected.hex}. Appearance layer: simulated. measured_qc_status = NOT_MEASURED.`}
  ['material','finish','illuminant','angle','depth'].forEach(id=>$('#'+id).oninput=drawSimulation);
  const workflows=[
    {name:'Inkscape',version:'v0.3.0',status:'WORKING REFERENCE HANDOFF',can:'Select an SVG fill or stroke, match it to the full ATLAS master, and write the frozen reference back with an audit record.',verified:'Direct fill, stroke and CSS handoff were validated for the documented extension version.',next:'Install and test the extension in the user’s own Inkscape environment before production use.',steps:['Choose SVG colour','Match full master','Freeze identity','Write colour','Review audit']},
    {name:'GIMP',version:'v0.1.3',status:'ENGINEERING BETA',can:'Select an 8-bit sRGB image pixel and bind it deterministically to one ATLAS reference identity.',verified:'The documented pixel-to-reference example and frozen source identity passed the engineering checks.',next:'Broader runtime and image-workflow testing is still required. This is not an image-wide physical proof.',steps:['Choose pixel','Read sRGB','Match full master','Freeze identity','Document result']},
    {name:'Krita',version:'v0.3.4',status:'RUNTIME TEST REQUIRED',can:'Search the full master from a Krita document colour and retain the selected ATLAS identity.',verified:'The plugin package and identity boundary are documented.',next:'The current package must still pass the stated installation and full-master UI runtime gate in Krita.',steps:['Choose colour','Search master','Select reference','Freeze row ID','Run audit']},
    {name:'Scribus',version:'PLANNED MVP',status:'NOT YET A FINISHED INTEGRATION',can:'The planned proof will carry one frozen identity into a separate print-production workflow.',verified:'Only the architecture and separation of identity from production mapping are currently documented.',next:'Bind a real ICC profile, generate and inspect PDF/X, then compare a measured physical print. No print result is currently verified.',steps:['Frozen identity','Check feasibility','Create device values','Inspect PDF/X','Measure print later']}
  ];
  function showWorkflow(i){const w=workflows[i];$('#workflow-detail').innerHTML=`<div class="connection-title"><div><p class="eyebrow">${esc(w.version)}</p><h3>ATLAS Clarus × ${esc(w.name)}</h3></div><span class="connection-status">${esc(w.status)}</span></div><div class="connection-explain"><article><span>WHAT YOU CAN DO</span><p>${esc(w.can)}</p></article><article><span>WHAT IS VERIFIED</span><p>${esc(w.verified)}</p></article><article><span>WHAT IS STILL NEEDED</span><p>${esc(w.next)}</p></article></div><h4 class="flow-label">The handoff in five steps</h4><div class="steps">${w.steps.map((s,n)=>`<div class="step"><strong>0${n+1}</strong>${esc(s)}</div>`).join('')}</div><p class="boundary"><b>Identity rule:</b> The PKL Full Reference remains authoritative. Application and production values may be appended, but they cannot redefine the frozen source identity.</p>`}
  workflows.forEach((w,i)=>{const b=document.createElement('button');b.className='workflow-card';b.innerHTML=`<b>${esc(w.name)}</b><span>${esc(w.version)}</span><em>${esc(w.status)}</em>`;b.onclick=()=>showWorkflow(i);$('#workflow-cards').append(b)});
  if(doc.master_sha256!==MASTER||colors.length!==13283||!libraryViews.core||libraryViews.core.ids.length!==13283){document.body.innerHTML='<main class="view active"><h1>Bundle validation failed</h1><p>The embedded master metadata, reference count or library views do not match the release baseline.</p></main>';return}
  select(selected);render();showWorkflow(0);route();
})();
